from astropy.io import fitsimport numpy as npimport matplotlib.pyplot as pltimport globfolder = "data/koa/HIRES/KELT-1/lev1/extracted/HI.20170702.51878"# lithium linetarget_wave = 6707.8# tighter lithium regionregion_min = 6695region_max = 6720# EW bounds (include Li + Fe)ew_min = 6706.8ew_max = 6709.2# radial velocity correctionv_rad = 65.0c = 299792.458z = v_rad / cfiles = sorted(glob.glob(f"{folder}/*.fits*"))print(f"Found {len(files)} files")found_any = False# helper to get wavelength/fluxdef get_wave_flux(table):    colnames = [name.upper() for name in table.columns.names]    wave = None    flux = None    for name in ["WAVELENGTH", "WAVE", "LAMBDA", "WL"]:        if name in colnames:            wave = table[name]            break    for name in ["FLUX", "SPEC", "SPECTRUM", "SCI", "COUNTS"]:        if name in colnames:            flux = table[name]            break    if wave is None or flux is None:        wave = table.field(0)        flux = table.field(1)    return np.ravel(wave), np.ravel(flux)for file in files:    print(f"\nTrying: {file}")    try:        with fits.open(file) as hdul:            if len(hdul) < 2 or hdul[1].data is None:                continue            table = hdul[1].data            wave, flux = get_wave_flux(table)        # clean        mask = np.isfinite(wave) & np.isfinite(flux)        wave = wave[mask]        flux = flux[mask]        if len(wave) == 0:            continue        # sort        idx = np.argsort(wave)        wave = wave[idx]        flux = flux[idx]        # Doppler correction        wave = wave / (1 + z)        # check lithium coverage        if not ((np.min(wave) < target_wave) and (np.max(wave) > target_wave)):            print("  -> No lithium region")            continue        # extract region        region_mask = (wave >= region_min) & (wave <= region_max)        wave_region = wave[region_mask]        flux_region = flux[region_mask]        if len(wave_region) < 10:            continue        # sort again        idx = np.argsort(wave_region)        wave_region = wave_region[idx]        flux_region = flux_region[idx]        # CONTINUUM FIT        continuum_mask = ((wave_region > 6704.5) & (wave_region < 6706.5)) | \                         ((wave_region > 6709.5) & (wave_region < 6711.5))        cont_wave = wave_region[continuum_mask]        cont_flux = flux_region[continuum_mask]        if len(cont_wave) < 5:            print("  -> Not enough continuum")            continue        # remove outliers        median = np.median(cont_flux)        std = np.std(cont_flux)        good = np.abs(cont_flux - median) < 2 * std        cont_wave = cont_wave[good]        cont_flux = cont_flux[good]        # fit line        coeffs = np.polyfit(cont_wave, cont_flux, 1)        continuum = np.polyval(coeffs, wave_region)        # normalize        flux_norm = flux_region / continuum        # EW CALC        ew_mask = (wave_region >= ew_min) & (wave_region <= ew_max)        wave_ew = wave_region[ew_mask]        flux_ew = flux_norm[ew_mask]        if len(wave_ew) < 2:            print("  -> Not enough points for EW")            continue        ew = np.trapz(1 - flux_ew, wave_ew)        print(f"  -> Li Equivalent Width = {ew:.4f} Å")        # smooth for plotting        window = 7        flux_smooth = np.convolve(flux_norm, np.ones(window)/window, mode="same")        # plot        plt.figure(figsize=(8,5))        plt.plot(wave_region, flux_smooth, label="Smoothed Spectrum")        plt.fill_between(wave_ew, flux_ew, 1.0, alpha=0.3, label="EW region")        plt.axvline(target_wave, color="red", linestyle="--", label="Li 6707.8 Å")        plt.axhline(1.0, color="gray", linestyle="--")        plt.xlim(6695, 6720)        plt.ylim(min(flux_smooth)-0.05, 1.1)        plt.xlabel("Rest Wavelength (Å)")        plt.ylabel("Normalized Flux")        plt.title(f"Lithium Equivalent Width = {ew:.4f} Å")        plt.legend()        plt.tight_layout()        plt.show()        found_any = True        break    except Exception as e:        print(f"  -> Error: {e}")if not found_any:    print("\nNo usable lithium spectrum found.")